1	import { useQuery } from "@tanstack/react-query";
2	import { useLocation } from "wouter";
3	import { propFetch } from "@/lib/property-api";
4	import { StatCarousel } from "./stat-carousel";
5	
6	/* ── Design tokens ── */
7	const C = {
8	  navy:  '#040D6D',
9	  sky:   '#58ABFF',
10	  btn:   '#3F9BFF',
11	  white: '#FFFFFF',
12	  mute:  '#8C8C8C',
13	};
14	
15	const STATUS_MAP: Record<string, { dot: string; bg: string; fg: string; label: string }> = {
16	  paid:     { dot: '#13C29A', bg: 'rgba(19,194,154,0.14)',  fg: '#0B7D63', label: 'paid' },
17	  overdue:  { dot: '#FF3B4E', bg: 'rgba(255,59,78,0.12)',   fg: '#C71A2A', label: 'overdue' },
18	  failed:   { dot: '#FF8A00', bg: 'rgba(255,138,0,0.14)',   fg: '#B25A00', label: 'not delivered' },
19	  dueSoon:  { dot: '#FFB02E', bg: 'rgba(255,176,46,0.18)',  fg: '#9A6A00', label: 'due soon' },
20	  upcoming: { dot: '#3F9BFF', bg: 'rgba(63,155,255,0.16)',  fg: '#1A5FCC', label: 'upcoming' },
21	};
22	
23	const GLASS = {
24	  background: 'linear-gradient(140deg, rgba(255,255,255,0.92) 0%, rgba(234,238,244,0.72) 50%, rgba(220,227,240,0.62) 100%)',
25	  backdropFilter: 'blur(16px) saturate(130%)',
26	  WebkitBackdropFilter: 'blur(16px) saturate(130%)',
27	  border: '1px solid rgba(255,255,255,0.7)',
28	  boxShadow: '0 12px 32px rgba(4,13,109,0.10), inset 0 1px 0 rgba(255,255,255,0.95)',
29	} as React.CSSProperties;
30	
31	/* ── Helpers ── */
32	function fmtCents(c: number) { return '$' + (c / 100).toLocaleString('en-NZ', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
33	
34	function invoiceStatus(inv: any): string {
35	  if (inv.status === 'paid' || inv.status === 'paid_external') return 'paid';
36	  if (inv.status === 'overdue') return 'overdue';
37	  if (inv.status === 'dispatch_failed') return 'failed';
38	  return 'upcoming';
39	}
40	
41	/* ── Status badge ── */
42	function StatusBox({ status }: { status: string }) {
43	  const s = STATUS_MAP[status] ?? STATUS_MAP.upcoming;
44	  return (
45	    <div style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '4px 9px', borderRadius: 8, background: s.bg, color: s.fg, fontWeight: 600, fontSize: 9.5, letterSpacing: '0.06em', textTransform: 'uppercase' }}>
46	      <span style={{ width: 6, height: 6, borderRadius: 999, background: s.dot, flexShrink: 0 }} />
47	      {s.label}
48	    </div>
49	  );
50	}
51	
52	/* ── Collection gauge ── */
53	function Ring({ pct }: { pct: number }) {
54	  const cx = 65, cy = 65, r = 48, diskR = 37;
55	  const circ = 2 * Math.PI * r;
56	  const p = Math.max(0.01, Math.min(1, pct));
57	  const endAng = (135 + 360 * p) * Math.PI / 180;
58	  return (
59	    <svg width="130" height="130" viewBox="0 0 130 130" style={{ display: 'block' }}>
60	      <defs>
61	        <filter id="pg-disk" x="-90%" y="-90%" width="280%" height="280%">
62	          <feDropShadow dx="0" dy="2.5" stdDeviation="7" floodColor="rgba(4,13,109,0.22)" />
63	        </filter>
64	        <filter id="pg-arc" x="-80%" y="-80%" width="260%" height="260%">
65	          <feDropShadow dx="0" dy="0.5" stdDeviation="4" floodColor="#040D6D" floodOpacity="0.32" />
66	        </filter>
67	      </defs>
68	      <circle cx={cx} cy={cy} r={diskR} fill="#EAEAEA" filter="url(#pg-disk)" />
69	      <circle cx={cx} cy={cy} r={r} fill="none" stroke="#FFFFFF" strokeOpacity="0.8" strokeWidth="1.5" />
70	      <circle cx={cx} cy={cy} r={r} fill="none" stroke={C.navy} strokeWidth="2.5" strokeLinecap="round"
71	        strokeDasharray={`${circ * p} ${circ}`} transform={`rotate(135 ${cx} ${cy})`} filter="url(#pg-arc)" />
72	      <circle cx={cx + r * Math.cos(endAng)} cy={cy + r * Math.sin(endAng)} r="5.5" fill={C.navy} filter="url(#pg-arc)" />
73	      <text x={cx} y={cy + 6} textAnchor="middle" fontFamily="system-ui,sans-serif" fontWeight="400" fontSize="19" fill={C.navy}>
74	        {Math.round(p * 100)}%
75	      </text>
76	    </svg>
77	  );
78	}
79	
80	/* ── Stat icon SVGs ── */
81	function IcoTenants({ c = C.navy }: { c?: string }) {
82	  return <svg width={17} height={17} viewBox="0 0 24 24" fill={c}><circle cx="8.5" cy="8" r="3"/><circle cx="16" cy="8.5" r="2.4"/><path d="M2.6 19c0-3.2 2.6-5.6 5.9-5.6s5.9 2.4 5.9 5.6z"/><path d="M15.4 13.6c2.6.2 4.9 2.3 4.9 5.1"/></svg>;
83	}
84	function IcoWarn({ c = C.navy }: { c?: string }) {
85	  return <svg width={17} height={17} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth="1.8" strokeLinecap="round"><path d="M12 3.6 21 19H3z"/><path d="M12 10v4.1"/><circle cx="12" cy="16.6" r=".95" fill={c} stroke="none"/></svg>;
86	}
87	function IcoPage({ c = C.navy }: { c?: string }) {
88	  return <svg width={17} height={17} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth="1.8" strokeLinecap="round"><path d="M6 3h8l4 4v14H6z"/><path d="M14 3v4h4"/><path d="M9 12h6M9 15.5h6"/></svg>;
89	}
90	function IcoPause({ c = C.navy }: { c?: string }) {
91	  return <svg width={17} height={17} viewBox="0 0 24 24" fill={c}><rect x="6.5" y="4.5" width="3.6" height="15" rx="1.3"/><rect x="13.9" y="4.5" width="3.6" height="15" rx="1.3"/></svg>;
92	}
93	
94	const STAT_ICONS = [IcoTenants, IcoWarn, IcoPage, IcoPause];
95	
96	export default function PropertyDashboard() {
97	  const [, setLocation] = useLocation();
98	
99	  const { data: tenants = [] } = useQuery<any[]>({
100	    queryKey: ['/api/property/tenants'],
101	    queryFn: () => propFetch('/api/property/tenants').then(r => { if (!r.ok) throw new Error('load failed'); return r.json(); }),
102	    staleTime: 60000,
103	    retry: false,
104	  });
105	
106	  const { data: invoices = [], isLoading: invLoading, isError: invError, refetch: refetchInv } = useQuery<any[]>({
107	    queryKey: ['/api/property/invoices'],
108	    queryFn: () => propFetch('/api/property/invoices').then(r => { if (!r.ok) throw new Error('load failed'); return r.json(); }),
109	    staleTime: 30000,
110	    retry: false,
111	  });
112	
113	  const { data: schedules = [] } = useQuery<any[]>({
114	    queryKey: ['/api/property/schedules'],
115	    queryFn: () => propFetch('/api/property/schedules').then(r => { if (!r.ok) throw new Error('load failed'); return r.json(); }),
116	    staleTime: 60000,
117	    retry: false,
118	  });
119	
120	  /* Derived stats — voided invoices are excluded from collection/recent so a
121	     cancelled request never drags down the rate or shows as a live payment. */
122	  const liveInvoices    = invoices.filter((i: any) => i.status !== 'voided');
123	  const activeTenants   = tenants.filter((t: any) => t.status !== 'archived').length;
124	  const overdueCount    = invoices.filter((i: any) => i.status === 'overdue').length;
125	  const queuedCount     = invoices.filter((i: any) => i.status === 'pending_dispatch').length;
126	  const activeCount     = invoices.filter((i: any) => ['pending_dispatch', 'dispatched', 'overdue', 'dispatch_failed'].includes(i.status)).length;
127	  const paidCount       = liveInvoices.filter((i: any) => i.status === 'paid' || i.status === 'paid_external').length;
128	  const collectionPct   = liveInvoices.length > 0 ? paidCount / liveInvoices.length : 0;
129	
130	  const now = new Date();
131	  const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
132	  const monthlyRevenue = invoices
133	    .filter((i: any) => (i.status === 'paid' || i.status === 'paid_external') && i.paidAt && new Date(i.paidAt) >= monthStart)
134	    .reduce((s: number, i: any) => s + (i.amountCents ?? 0), 0);
135	
136	  const recent = [...liveInvoices]
137	    .sort((a: any, b: any) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
138	    .slice(0, 3);
139	
140	  const stats = [
141	    { label: 'tenants',     v: activeTenants, Ico: STAT_ICONS[0] },
142	    { label: 'outstanding', v: overdueCount,  Ico: STAT_ICONS[1] },
143	    { label: 'queued',      v: queuedCount,   Ico: STAT_ICONS[2] },
144	    { label: 'paused',      v: schedules.filter((s: any) => s.status === 'paused').length, Ico: STAT_ICONS[3] },
145	  ];
146	
147	  return (
148	    <div style={{ background: C.white, minHeight: '100svh', display: 'flex', justifyContent: 'center' }}>
149	    <div style={{ width: '100%', maxWidth: 430, minHeight: '100svh', background: '#F4F4F4', paddingBottom: 130, fontFamily: "'Outfit', system-ui, sans-serif" }}>
150	      <div style={{ height: 54 }} />
151	
152	      {/* Load error — show a retry instead of silently rendering zeros */}
153	      {invError && (
154	        <div style={{ margin: '0 18px 12px', padding: '14px 16px', borderRadius: 16, background: 'rgba(255,59,78,0.08)', border: '1px solid rgba(255,59,78,0.2)', display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 12 }}>
155	          <span style={{ color: '#C71A2A', fontSize: 13, fontWeight: 500 }}>{invLoading ? 'loading…' : "couldn't load your data"}</span>
156	          <button onClick={() => refetchInv()} style={{ background: C.navy, color: C.white, border: 'none', borderRadius: 10, padding: '8px 14px', fontSize: 12, fontWeight: 700, cursor: 'pointer' }}>retry</button>
157	        </div>
158	      )}
159	
160	      {/* 1 — Active transaction hero */}
161	      <div style={{ padding: '0 18px' }}>
162	        <div style={{ background: C.navy, borderRadius: 24, padding: '24px 26px 26px' }}>
163	          <div style={{ fontWeight: 900, fontSize: 62, color: C.sky, letterSpacing: '-0.04em', lineHeight: 0.92, fontVariantNumeric: 'tabular-nums' }}>
164	            {activeCount}
165	          </div>
166	          <div style={{ fontWeight: 500, fontSize: 12, color: C.sky, letterSpacing: '0.16em', textTransform: 'uppercase', marginTop: 6 }}>
167	            active transaction{activeCount !== 1 ? 's' : ''}
168	          </div>
169	          <div style={{ marginTop: 18, height: 24, borderRadius: 999, border: `1.5px solid ${C.sky}`, padding: 3 }}>
170	            <div style={{ width: `${Math.max(4, collectionPct * 100)}%`, height: '100%', borderRadius: 999, background: C.sky, transition: 'width 0.8s ease' }} />
171	          </div>
172	        </div>
173	      </div>
174	
175	      {/* 2 — Revenue + gauge row */}
176	      <div style={{ display: 'grid', gridTemplateColumns: '1.32fr 1fr', gap: 14, padding: '16px 18px 0' }}>
177	        <div style={{ background: C.sky, borderRadius: 22, padding: '24px 22px', display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
178	          <div style={{ fontWeight: 900, fontSize: 36, color: C.navy, letterSpacing: '-0.04em', lineHeight: 1, fontVariantNumeric: 'tabular-nums' }}>
179	            {fmtCents(monthlyRevenue)}
180	          </div>
181	          <div style={{ fontWeight: 500, fontSize: 11, color: C.navy, letterSpacing: '0.08em', textTransform: 'uppercase', marginTop: 12, lineHeight: 1.3 }}>
182	            monthly rent<br />revenue
183	          </div>
184	        </div>
185	        <div style={{ background: '#F2F0F0', borderRadius: 22, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
186	          <Ring pct={collectionPct} />
187	        </div>
188	      </div>
189	
190	      {/* 3 — Stat carousel */}
191	      <StatCarousel stats={stats} />
192	
193	      {/* 4 — Rent transactions */}
194	      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '22px 20px 12px' }}>
195	        <div style={{ fontWeight: 600, fontSize: 12, color: C.navy, letterSpacing: '0.12em', textTransform: 'uppercase' }}>rent transactions</div>
196	        <button onClick={() => setLocation('/property/tenants')} style={{ fontSize: 13, fontWeight: 600, color: C.btn, background: 'none', border: 'none', cursor: 'pointer' }}>view all →</button>
197	      </div>
198	
199	      {recent.length === 0 ? (
200	        <div style={{ padding: '32px 18px', textAlign: 'center', color: C.mute, fontSize: 13 }}>
201	          no transactions yet — add tenants to get started
202	        </div>
203	      ) : (
204	        <div style={{ display: 'flex', flexDirection: 'column', gap: 12, padding: '0 18px' }}>
205	          {recent.map((inv: any) => {
206	            const name     = inv.tenantName || '—';
207	            const initials = name.split(' ').map((w: string) => w[0]).join('').slice(0, 2).toUpperCase();
208	            return (
209	              <div key={inv.id} style={{ ...GLASS, borderRadius: 18, padding: '14px 16px', display: 'flex', alignItems: 'center', gap: 13 }}>
210	                <div style={{ width: 40, height: 40, borderRadius: 999, background: C.navy, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0, fontWeight: 800, fontSize: 12, color: C.sky, letterSpacing: '0.03em' }}>
211	                  {initials}
212	                </div>
213	                <div style={{ flex: 1, minWidth: 0 }}>
214	                  <div style={{ fontWeight: 500, fontSize: 13.5, color: C.navy, textTransform: 'capitalize', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{name}</div>
215	                  <div style={{ fontWeight: 400, fontSize: 11, color: C.mute, marginTop: 2, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{inv.propertyAddress || '—'}</div>
216	                </div>
217	                <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 5, flexShrink: 0 }}>
218	                  {(() => {
219	                    const isSplit = inv.splitEnabled && inv.splitCount > 1;
220	                    const paid = inv.splitPaidCount || 0;
221	                    const showOwing = isSplit && paid > 0 && invoiceStatus(inv) !== 'paid';
222	                    return (
223	                      <>
224	                        <div style={{ fontWeight: 700, fontSize: 14, color: C.navy, fontVariantNumeric: 'tabular-nums' }}>{fmtCents(showOwing ? (inv.owingCents ?? inv.amountCents) : (inv.amountCents ?? 0))}</div>
225	                        {isSplit && <div style={{ fontSize: 9.5, fontWeight: 700, color: '#0B7D63' }}>{paid}/{inv.splitCount} split</div>}
226	                      </>
227	                    );
228	                  })()}
229	                  <StatusBox status={invoiceStatus(inv)} />
230	                </div>
231	              </div>
232	            );
233	          })}
234	        </div>
235	      )}
236	    </div>
237	    </div>
238	  );
239	}
