1	import { useState, useEffect, useRef } from "react";
2	import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
3	import { useLocation } from "wouter";
4	import { propFetch } from "@/lib/property-api";
5	
6	/* ═══ TOKENS ═══ */
7	const NAVY = '#040D6D';
8	const BLUE = '#58ABFF';
9	const OFFW = '#F4F4F4';
10	const GREEN = '#1BBF85';
11	const RED   = '#FF3B4E';
12	const AMBER = '#FFB02E';
13	
14	const fmt = (c: number) => `$${(c / 100).toFixed(2)}`;
15	
16	function tenantInitials(t: any) {
17	  return `${t.firstName?.[0] ?? ''}${t.lastName?.[0] ?? ''}`.toUpperCase();
18	}
19	function tenantName(t: any) { return `${t.firstName} ${t.lastName}`; }
20	
21	function invoiceStatusFor(inv: any) {
22	  if (inv.status === 'paid' || inv.status === 'paid_external') return 'paid';
23	  if (inv.status === 'overdue') return 'overdue';
24	  if (inv.status === 'dispatch_failed') return 'failed';
25	  if (inv.status === 'dispatched') return 'sent';
26	  return 'awaiting';
27	}
28	
29	/* ═══ ICONS ═══ */
30	const Ic = {
31	  X:       ({ sz = 18, sw = 2.4 }: any) => <svg width={sz} height={sz} viewBox="0 0 24 24" fill="none"><path d="M5 5l14 14M19 5L5 19" stroke="currentColor" strokeWidth={sw} strokeLinecap="round"/></svg>,
32	  Check:   ({ sz = 20, sw = 2.4 }: any) => <svg width={sz} height={sz} viewBox="0 0 24 24" fill="none"><path d="M4 12.5l5 5L20 6.5" stroke="currentColor" strokeWidth={sw} strokeLinecap="round" strokeLinejoin="round"/></svg>,
33	  Plus:    ({ sz = 28, sw = 3   }: any) => <svg width={sz} height={sz} viewBox="0 0 24 24" fill="none"><path d="M12 4v16M4 12h16" stroke="currentColor" strokeWidth={sw} strokeLinecap="round"/></svg>,
34	  Back:    ({ sz = 22           }: any) => <svg width={sz} height={sz} viewBox="0 0 24 24" fill="none"><path d="M15 6l-6 6 6 6" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"/></svg>,
35	  Arrow:   () => <svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke={NAVY} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="3" y1="8" x2="13" y2="8"/><polyline points="9,4 13,8 9,12"/></svg>,
36	  Person:  ({ sz = 20, c = NAVY }: any) => <svg width={sz} height={sz} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="7.5" r="4"/><path d="M3.5 21c0-4 3.8-7 8.5-7s8.5 3 8.5 7"/></svg>,
37	  People:  ({ sz = 20, c = NAVY }: any) => <svg width={sz} height={sz} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round"><circle cx="9" cy="7" r="3.5"/><circle cx="17" cy="8" r="2.5"/><path d="M2 20c0-3.5 3.1-6 7-6s7 2.5 7 6"/><path d="M18 14c2.2.3 4 2 4 4.5"/></svg>,
38	  Send:    ({ sz = 20, c = NAVY }: any) => <svg width={sz} height={sz} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round"><path d="M21 4 3 11l6 2.5L12 20l3-7z"/><path d="m9 13.5 6-6.5"/></svg>,
39	  External:({ sz = 20, c = NAVY }: any) => <svg width={sz} height={sz} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round"><path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 01-2 2H5a2 2 0 01-2-2V5a2 2 0 012-2h7"/></svg>,
40	  Search:  ({ sz = 18, c = NAVY }: any) => <svg width={sz} height={sz} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth="2" strokeLinecap="round"><circle cx="11" cy="11" r="6.5"/><path d="m20 20-3.5-3.5"/></svg>,
41	  Mail:    ({ sz = 18, c = BLUE }: any) => <svg width={sz} height={sz} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><rect x="2" y="4" width="20" height="16" rx="2"/><path d="M2 7l10 7 10-7"/></svg>,
42	  Msg:     ({ sz = 18, c = BLUE }: any) => <svg width={sz} height={sz} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15a2 2 0 01-2 2H7l-4 4V5a2 2 0 012-2h14a2 2 0 012 2z"/></svg>,
43	  Repeat:  ({ sz = 20, c = NAVY }: any) => <svg width={sz} height={sz} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round"><path d="M17 2l3 3-3 3"/><path d="M3 11V9a4 4 0 014-4h13"/><path d="M7 22l-3-3 3-3"/><path d="M21 13v2a4 4 0 01-4 4H4"/></svg>,
44	  Pause:   ({ sz = 18, c = NAVY }: any) => <svg width={sz} height={sz} viewBox="0 0 24 24" fill={c}><rect x="6" y="4.5" width="4" height="15" rx="1.4"/><rect x="14" y="4.5" width="4" height="15" rx="1.4"/></svg>,
45	  Play:    ({ sz = 18, c = NAVY }: any) => <svg width={sz} height={sz} viewBox="0 0 24 24" fill={c}><path d="M7 4.5l12 7.5-12 7.5z"/></svg>,
46	  Trash:   ({ sz = 18, c = NAVY }: any) => <svg width={sz} height={sz} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round"><path d="M4 7h16M9 7V5a1 1 0 011-1h4a1 1 0 011 1v2M6 7l1 13a1 1 0 001 1h8a1 1 0 001-1l1-13"/></svg>,
47	  Receipt: ({ sz = 20, c = NAVY }: any) => <svg width={sz} height={sz} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round"><path d="M6 3h12v18l-3-2-3 2-3-2-3 2z"/><path d="M9 8h6M9 12h6"/></svg>,
48	};
49	
50	/* ═══ SUBBAR — 4 items (send rent · bill extras · record external) ═══ */
51	const SUBBAR_ITEMS = [
52	  { id: 'tenants',  label: 'tenants',  Icon: Ic.Person   },
53	  { id: 'send',     label: 'send',     Icon: Ic.Send     },
54	  { id: 'bill',     label: 'bill',     Icon: Ic.Receipt  },
55	  { id: 'external', label: 'external', Icon: Ic.External },
56	];
57	const SCREEN_TO_SUBBAR: Record<string, number> = { tenants: 0, send: 1, bill: 2, external: 3 };
58	const SUBBAR_ROUTE: Record<number, string> = { 0: 'tenants', 1: 'send', 2: 'bill', 3: 'external' };
59	
60	/* ═══ CHARGES (Bill) ═══ */
61	const CHARGE_TYPES = [
62	  { id: 'utilities', label: 'water / utilities', preset: 'Water / utilities' },
63	  { id: 'late_fee',  label: 'late fee',          preset: 'Late fee'          },
64	  { id: 'cleaning',  label: 'cleaning',          preset: 'Cleaning'          },
65	  { id: 'damages',   label: 'damages',           preset: 'Damages'           },
66	  { id: 'other',     label: 'other',             preset: ''                  },
